import React, { useState } from "react";
import { Link } from "react-router-dom";
import wordCloudImage from "./test1.jpg";

export default function Summary() {
  const [hovered, setHovered] = useState(false);

  const containerWidth = 320; // full width when expanded
  const collapsedWidth = 50;  // width when collapsed

  return (
    <div
      style={{
        position: "relative",
        minHeight: "100vh",
        padding: "2rem",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
        background: "linear-gradient(135deg, #11998e 0%, #ffc3a0 100%)",
        color: "#333",
        textAlign: "center",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Main Summary Section */}
      <div>
        <h2 style={{ fontSize: "2.5rem", fontWeight: "700", marginBottom: "1rem" }}>
          Summary of Comments
        </h2>
        <p style={{ fontSize: "1.2rem", opacity: 0.85 }}>
          👉 Your summary output will appear here...
        </p>
        <Link to="/" style={{ marginTop: "2rem", textDecoration: "none", display: "inline-block" }}>
          <button
            style={{
              background: "linear-gradient(135deg, #6a11cb 0%, #2575fc 100%)",
              border: "none",
              borderRadius: "30px",
              padding: "12px 28px",
              fontSize: "1.1rem",
              fontWeight: "600",
              color: "#fff",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(37, 117, 252, 0.6)",
              transition: "all 0.3s ease",
              minWidth: "180px",
            }}
            onMouseEnter={(e) => {
              e.target.style.background = "linear-gradient(135deg, #2575fc 0%, #6a11cb 100%)";
              e.target.style.boxShadow = "0 6px 20px rgba(106, 17, 203, 0.75)";
            }}
            onMouseLeave={(e) => {
              e.target.style.background = "linear-gradient(135deg, #6a11cb 0%, #2575fc 100%)";
              e.target.style.boxShadow = "0 4px 15px rgba(37, 117, 252, 0.6)";
            }}
          >
            Back
          </button>
        </Link>
      </div>

      {/* Combined Word Cloud Frame */}
      <div
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        style={{
          position: "fixed",
          right: hovered ? 0 : `-${containerWidth - collapsedWidth}px`,
          top: 0,
          height: "100vh",
          width: `${containerWidth}px`,
          backgroundColor: "#fff",
          boxShadow: "0 0 15px rgba(0,0,0,0.2)",
          display: "flex",
          alignItems: "center",
          padding: "0 10px 0 10px",
          transition: "right 0.3s ease",
          zIndex: 1100,
          overflow: "hidden",
          borderTopLeftRadius: "15px",
          borderBottomLeftRadius: "15px",
        }}
      >
        {/* Word Cloud Image fills most of the container */}
        <img
          src={wordCloudImage}
          alt="wordcloud"
          style={{
            width: `${containerWidth - collapsedWidth}px`,
            height: "auto",
            borderRadius: "15px 0 0 15px",
            flexShrink: 0,
          }}
        />

        {/* Vertical Word Cloud Text */}
        <div
          style={{
            writingMode: "vertical-rl",
            textOrientation: "mixed",
            marginLeft: "10px",
            color: "#6a11cb",
            fontWeight: "700",
            fontSize: hovered ? "1.8rem" : "1.2rem",
            letterSpacing: "0.15em",
            transition: "font-size 0.3s ease",
            userSelect: "none",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            height: "100%",
          }}
        >
          Word Cloud
        </div>
      </div>
    </div>
  );
}
